# Insert
total = 0
for table, rows in questions.items():
    cur.executemany(f"""
        INSERT INTO `{table}`
        (difficulty, question, option_a, option_b, option_c, option_d, correct_answer, explanation)
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
    """, rows)
    count = len(rows)
    total += count
    print(f"  {table}: {count} questions inserted")

conn.commit()

print(f"\nTotal questions inserted: {total}")

# Verify
for table in topics:
    cur.execute(f"SELECT difficulty, COUNT(*) FROM `{table}` GROUP BY difficulty ORDER BY difficulty")
    rows = cur.fetchall()
    print(f"\n{table}:")
    for r in rows:
        print(f"  {r[0]}: {r[1]}")

conn.close()
print("\nDatabase created successfully!")